Field.Calculation:
Let (
  [
    $today = Get ( 日付 ) ;
    $本日稼働日 =
      ExecuteSQL ("
        SELECT \"c_月次稼働日数\"
        FROM \"カレンダー\"
        WHERE \"年月日\" = ?
        " ;
        "" ; "" ;
        $today
      )
  ] ;
  Case ( 年月 < GetYYYYMM ( $today ) ; 0 ;
    ExecuteSQL ("
      SELECT \"c_月次総稼働日数\"
      FROM \"カレンダー\"
      WHERE \"年月日\" = ?
      " ;
      "" ; "" ;
      $today
    ) - $本日稼働日
  )
) & "日"

DisplayCalculation.Chunk:
("
       SELECT \"c_月次稼働日数\"
       FROM \"カレンダー\"
       WHERE \"年月日\" = ?
       " ;
       "" ; "" ;
       $today
     )
 ] ;

 ("
      SELECT \"c_月次総稼働日数\"
      FROM \"カレンダー\"
      WHERE \"年月日\" = ?
      " ;
      "" ; "" ;
      $today
    ) - $本日稼働日
  )
) & "日"

Field.Calculation:
Case ( IsEmpty ( 今年度実績_15[ Get ( 計算式繰り返し位置番号 ) ] ) or IsEmpty ( 今年度目標_14[ Get ( 計算式繰り返し位置番号 ) ] ) 
 or 今年度目標_14[ Get ( 計算式繰り返し位置番号 ) ] = 0 or 今年度目標_14[ Get ( 計算式繰り返し位置番号 ) ] = 0 ; "0.0％" ;  
    ( 今年度実績_15[ Get ( 計算式繰り返し位置番号 ) ] /
      今年度目標_14[ Get ( 計算式繰り返し位置番号 ) ]
    )

)

Case ( IsEmpty ( 今年度実績_15[ Get ( 計算式繰り返し位置番号 ) ] ) or IsEmpty ( 前年度実績_15[ Get ( 計算式繰り返し位置番号 ) ] ) 
 or 今年度実績_15[ Get ( 計算式繰り返し位置番号 ) ] = 0 or 前年度実績_15[ Get ( 計算式繰り返し位置番号 ) ] = 0 ; "0.0％" ;  
    ( 今年度実績_15[ Get ( 計算式繰り返し位置番号 ) ] /
      前年度実績_15[ Get ( 計算式繰り返し位置番号 ) ]
  )
)

Case ( IsEmpty ( 今年度実績_15[15] ) or IsEmpty ( 前年度実績_15[15] )
 or 今年度実績_15[15] = 0 or 前年度実績_15[15] = 0 ; "0.0%" ;  
(今年度実績_15[15]/(前年度平均 * Case ( GetAsNumber ( Right ( FC拠点別集計::年月 ; 2 ) ) > 3 ;Right ( FC拠点別集計::年月 ; 2 ) - 3 ;Right ( FC拠点別集計::年月 ; 2 ) + 9))) - 1)

Case (
    IsEmpty ( FC拠点別集計::当月実績金額 )
    or IsEmpty ( FC拠点別集計::当月目標金額 )
    or FC拠点別集計::当月実績金額 = 0
    or FC拠点別集計::当月目標金額 = 0 ;

    "0.0％" ;

        FC拠点別集計::当月実績金額 / FC拠点別集計::当月目標金額 

    ) & "％"

Case (
    IsEmpty ( FC拠点別集計::週次売上実績_6[ Get ( 計算式繰り返し位置番号 ) ] )
    or IsEmpty ( FC拠点別集計::週次設定目標_6[ Get ( 計算式繰り返し位置番号 ) ] )
    or FC拠点別集計::週次売上実績_6[ Get ( 計算式繰り返し位置番号 ) ] = 0
    or FC拠点別集計::週次設定目標_6[ Get ( 計算式繰り返し位置番号 ) ] = 0 ;

    "0.0％" ;

        FC拠点別集計::週次売上実績_6[ Get ( 計算式繰り返し位置番号 ) ] / FC拠点別集計::週次設定目標_6[ Get ( 計算式繰り返し位置番号 ) ]
)

Case (
    IsEmpty ( FC拠点別集計::週次次月繰越 )
    or IsEmpty ( FC拠点別集計::週次売上実績_6[6] )
    or FC拠点別集計::週次次月繰越 = 0
    or FC拠点別集計::週次売上実績_6[6] = 0 ;

    "0.0％" ;

