Field.Calculation:
If (
  IsEmpty ( 当月目標金額 )
  or IsEmpty ( 当月実績金額 )
  or 当月目標金額 = 0
  or 当月実績金額 = 0 ;

  "0.0％" ;

  Let ( [
     _ym = FC拠点別集計::年月 ;
     _now = GetYYYYMM ( Get ( 日付 ) ) ;
     _target =
       If (
         _ym = _now ;
         ((当月目標金額 * 1.2) / $$総稼働日数) * $$稼働日 ;
         (当月目標金額 * 1.2)
       )
  ] ;
    当月実績金額 / _target
  )
)

AutoEnter.Calculation:
Case ( 
  Month ( 年月日 )  ≥ 4 and Month ( 年月日 )  ≤ 12 ; 
  Year ( 年月日 ) ; 

  Month ( 年月日 )  ≥ 1 and Month ( 年月日 )  ≤ 3 ; 
  Year ( 年月日 ) - 1 ;

  ""
)

Field.Calculation:
GetAsNumber (
    ExecuteSQL (
      "SELECT COUNT(*)
       FROM \"カレンダー\"
       WHERE \"年月\" = ?
         AND ( \"非稼働日フラグ\" IS NULL OR \"非稼働日フラグ\" = 0 )"
      ; "" ; "" ;
      年月
    )
  )

Case ( 
  非稼働日フラグ = 1 ; 
  0 ; 

  ExecuteSQL (
    "SELECT COUNT(*)
     FROM \"カレンダー\"
     WHERE \"年月\" = ?
     AND \"年月日\" <= ?
     AND ( \"非稼働日フラグ\" IS NULL OR \"非稼働日フラグ\" = 0 )"
    ; "" ; "" ;
    年月 ; 年月日
  ) 
)

