If [ Let (
  [
    s = $startYM ;
    e = $endYM ;

    sOK =
      not IsEmpty ( s )
      and Length ( s ) = 6
      and Filter ( s ; "0123456789" ) = s
      and Right ( s ; 2 ) ≥ "01" and Right ( s ; 2 ) ≤ "12" ;

    eOK =
      not IsEmpty ( e )
      and Length ( e ) = 6
      and Filter ( e ; "0123456789" ) = e
      and Right ( e ; 2 ) ≥ "01" and Right ( e ; 2 ) ≤ "12"
  ] ;
    not ( sOK and eOK and s ≤ e )
) ]

