フィールド内容の全置換 [ FC拠点別集計::当月実績金額; 計算で置き換える: Let (
  [
    raw = ExecuteSQL (
      "
      SELECT 
          SUM ( \"OK実績\" )
      FROM 
          \"実績集計テーブル\"
      WHERE 
          \"加盟店セットCD\" = ?
          AND \"年月\" = ?
          AND (\"キャンセル日\" is null OR \"キャンセル日\" >= ? )
          AND (\"撤去日\" is null OR \"撤去日\" >= ? )
      " ;
      "" ; "" ;
      FC拠点別集計::加盟店セットCD ;
      FC拠点別集計::年月 ;
      Date ( Right ( FC拠点別集計::年月 ; 2 ) + 1 ; 1 ; Left ( FC拠点別集計::年月 ; 4 ) ) ;
      Date ( Right ( FC拠点別集計::年月 ; 2 ) + 1 ; 1 ; Left ( FC拠点別集計::年月 ; 4 ) )
    ) ;

    // 数値化（空→0）
    val = GetAsNumber ( raw )
  ] ;

  Case (
    val = 0 ;
      "0.0万円" ;

    Round ( val / 10000 ; 1 ) & "万円"
  )
) ]
[ ダイアログなし ]

