Step.StepText:
フィールド内容の全置換 [ FC拠点別集計::週次売上実績_6[$i]; 計算で置き換える: Let ( [
    _week = ExecuteSQL ( 
      " SELECT \"週リスト\" FROM \"SV担当者入力データ週次\" WHERE \"_月次ID\" = ? AND \"週番号\" = ? " ; 
      "" ; "" ; 
      FC拠点別集計_SV担当者入力データ月次::ID ; $i 
    ) ; 
    _weeklist = "'" & Substitute ( _week ; "," ; "','" ) & "'"
  ] ; 
  Case ( IsEmpty ( _week ) ; "" ;  
  Round (
    ExecuteSQL (
      "
      SELECT 
        SUM ( \"売上実績\" )
      FROM 
        \"実績集計テーブル\"
      WHERE 
        \"加盟店セットCD\" = ?
        AND \"年月\" = ?
        AND (\"キャンセル日\" is null OR \"キャンセル日\" >= ? )
        AND (\"撤去日\" is null OR \"撤去日\" >= ? )
        AND \"売上日\" IN ( " & _weeklist & " )
      " ;
      "" ; "" ;
      FC拠点別集計::加盟店セットCD ;
      FC拠点別集計::年月 ;
      Date ( Right ( FC拠点別集計::年月 ; 2 ) + 1 ; 1 ; Left ( FC拠点別集計::年月 ; 4 ) ) ;
      Date ( Right ( FC拠点別集計::年月 ; 2 ) + 1 ; 1 ; Left ( FC拠点別集計::年月 ; 4 ) )
    ) / 1000 ;
  0 ) )
) ]
