      "" ; "" ; FC拠点別集計::加盟店セットCD ; _nowMonthAgo 
    ) ; 

    /* 今月の週リストを改行区切りで取得 */
    _weekList = ExecuteSQL ( 
      " SELECT \"週リスト\" FROM \"SV担当者入力データ週次\" WHERE \"_月次ID\" = ? " ; 
      "" ; "" ; _nowMonthAgoID 
    ) ; 

    /* 週ごとの受注件数を改行区切りで取得 */
     _weekCount = While ( 
      [ i = 1 ; countList = "" ] ; 
      i ≤ ValueCount ( _weekList ) ; 
      [ 
        weekVal = "'" & Substitute ( GetValue ( _weekList ; i ) ; "," ; "','" ) & "'" ; 
        countList = countList & ExecuteSQL ( 
                      "SELECT COUNT(\"主キー\") FROM \"実績集計テーブル\"
                       WHERE \"年月\" = ? AND \"加盟店セットCD\" = ? 
                       AND ( \"キャンセル日\" IS NULL OR \"キャンセル年月\" > ? ) 
                       AND ( \"撤去日\" IS NULL OR \"撤去年月\" > ? )
                       AND \"OK日\" IN ( " & weekVal & " ) " ;
                      "" ; "" ; 
                      _nowMonthAgo ; 
                      FC拠点別集計::加盟店セットCD ; 
                      _nowMonthAgo ; 
                      _nowMonthAgo 
                    ) & "¶" ; 
        i = i + 1 
      ] ; 
      countList
    ) ;

    /* 今月の受注1件当たりの平均単価を取得 */
    _avgPrice = FormatPrice ( Round (  ExecuteSQL ( 
                  " SELECT AVG(\"OK実績\") FROM \"実績集計テーブル\"
                    WHERE \"年月\" = ? AND \"加盟店セットCD\" = ?
                    AND ( \"キャンセル日\" IS NULL OR \"キャンセル年月\" > ? ) 
                    AND ( \"撤去日\" IS NULL OR \"撤去年月\" > ? )
                    AND \"OK年月\" = ? " ; 
                  "" ; "" ; 
                  _nowMonthAgo ; 
                  FC拠点別集計::加盟店セットCD ; 
                  _nowMonthAgo ; 
                  _nowMonthAgo ; 
                  _nowMonthAgo
                ) / 1000 ; 0 ) ) ; 

    /* メモ欄作成に必要な値を設定 */
    _strMonth = "【" & GetAsNumber ( Right ( FC拠点別集計::年月 ; 2 ) ) & "月】 " ; 
    _strWeekOrder = While ( [ i = 1 ; weekOrder = "" ] ; i ≤ ValueCount ( _weekCount ) ; 
                      [ weekOrder = weekOrder &  i & "週" & GetValue ( _weekCount ; i ) & "件、" ; i = i + 1 ] ; 
                      weekOrder 
                    ) ; 
    _strAvgPrice = "平均単価 " & _avgPrice & "千円"
  ] ; 

  _strMonth & _strWeekOrder & _strAvgPrice
)

)

