変数を設定 [ $resultList; 値:Let (
[
  today = Date ( SV担当者入力データ月次::月 - 1 ; 1 ; SV担当者入力データ月次::年 ) ;

  // 取得対象の3か月の年月をそれぞれ算出
  y1 = Year ( today );
  m1 = Month ( today );

  date2 = Date ( m1 - 1 ; 1 ; y1 );
  y2 = Year ( date2 );
  m2 = Month ( date2 );

  date3 = Date ( m2 - 1 ; 1 ; y2 );
  y3 = Year ( date3 );
  m3 = Month ( date3 );


  m1Row = ExecuteSQL (
    "
    SELECT \"当月目標金額_月初_委託\",\"中間予測金額\",\"最終予測金額\",\"月次着地額_月次_委託\"
    FROM \"SV担当者入力データ月次\"
    WHERE \"加盟店セットCD\" = ?
    AND (
      (\"年\" = ? AND \"月\" = ?) 
    )
    ";
    ","; "¶";
    SV担当者入力データ月次::加盟店セットCD;
    y1; m1
    ) ; 

  m2Row = ExecuteSQL (
    "
    SELECT \"当月目標金額_月初_委託\",\"中間予測金額\",\"最終予測金額\",\"月次着地額_月次_委託\"
    FROM \"SV担当者入力データ月次\"
    WHERE \"加盟店セットCD\" = ?
    AND (
      (\"年\" = ? AND \"月\" = ?) 
    )
    ";
    ","; "¶";
    SV担当者入力データ月次::加盟店セットCD;
    y2; m2
    ) ; 

  m3Row = ExecuteSQL (
    "
    SELECT \"当月目標金額_月初_委託\",\"中間予測金額\",\"最終予測金額\",\"月次着地額_月次_委託\"
    FROM \"SV担当者入力データ月次\"
    WHERE \"加盟店セットCD\" = ?
    AND (
      (\"年\" = ? AND \"月\" = ?) 
    )
