Step.StepText:
変数を設定 [ $json; 値:Let ( [

  rows =
    ExecuteSQL (
      "SELECT \"週番号\", \"年月日\", \"非稼働日フラグ\"
       FROM \"カレンダー\"
       WHERE \"年月\" = ?
         AND \"週番号\" <> 0
       ORDER BY \"週番号\", \"年月日\"" ;
      "|" ; "¶" ;
      $ym
    ) ;

  // ----------------------------
  // ① weeks / workdays を作る
  // ----------------------------
  basejson =
    While (
      [
        r = 1 ;
        rc = ValueCount ( rows ) ;

        json =
          JSONSetElement ( "{}" ;
            [ "ym" ; $ym ; JSONString ] ;
            [ "weeks" ; "{}" ; JSONObject ]
          )
      ] ;

      r ≤ rc ;

      [
        row = GetValue ( rows ; r ) ;
        col = Substitute ( row ; "|" ; "¶" ) ;

        wk = GetAsNumber ( GetValue ( col ; 1 ) ) ;
        d  = GetValue ( col ; 2 ) ;
        f  = GetAsNumber ( GetValue ( col ; 3 ) ) ;

        json =
          Case (
            IsEmpty ( JSONGetElement ( json ; "weeks." & wk & ".weekstart" ) ) ;
            JSONSetElement ( json ;
              [ "weeks." & wk & ".weekstart" ; d ; JSONString ] ;
              [ "weeks." & wk & ".workdays" ; "[]" ; JSONArray ]
            ) ;
            json
          ) ;

        json =
            Let ( [
              path = "weeks." & wk & ".weekdays" ;
              idx  = ValueCount ( JSONListKeys ( json ; path ) )
            ] ;
              JSONSetElement ( json ;
                [ path & "[" & idx & "]" ; d ; JSONString ]
              )
            ) ;

        json =
          Case (
            f = 0 ;
            Let ( [
              path = "weeks." & wk & ".workdays" ;
              idx  = ValueCount ( JSONListKeys ( json ; path ) )
            ] ;
              JSONSetElement ( json ;
                [ path & "[" & idx & "]" ; d ; JSONString ]
              )
            ) ;
            json
          ) ;

        r = r + 1
      ] ;

      json
    )
] ;

  basejson
) ]

