Step.StepText:
変数を設定 [ $json; 値:Let ( [

  // ------------------------------------------
  // ② 各週に workdayCount / weeklyTarget を追記
  // ------------------------------------------
  weekKeys = JSONListKeys ( $json ; "weeks" ) ;

  finaljson =
    While (
      [
        i = 1 ;
        n = ValueCount ( weekKeys ) ;
        out = $json
      ] ;

      i ≤ n ;

      [
        wkTxt = GetValue ( weekKeys ; i ) ;
        path  = "weeks." & wkTxt & ".workdays" ;

        workdayCount = ValueCount ( JSONListKeys ( out ; path ) ) ;

        weeklyTarget =
          Case (
            $月次総稼働日数 > 0 ;
            $拠点当月目標 / $月次総稼働日数 * workdayCount ;
            0
          ) ;

        weeklyTarget = Round ( weeklyTarget ; 0 ) ;

        out =
          JSONSetElement ( out ;
            [ "weeks." & wkTxt & ".workdayCount" ; workdayCount ; JSONNumber ] ;
            [ "weeks." & wkTxt & ".weeklyTarget" ; weeklyTarget ; JSONNumber ]
          ) ;

        i = i + 1
      ] ;

      out
    )

] ;

  finaljson
) ]

