Let ( [
    y = Int ( Middle ( ym; 1 ; 4 ) ) ;
    m = Int ( Middle ( ym; 5 ; 2 ) ) - 1
] ;
    Case (
        m = 0 ;
        (y - 1) * 100 + 12 ;
        y * 100 + m
    )
)

Let ( [
    y = Int ( Middle ( ym; 1 ; 4 ) ) ;
    m = Int ( Middle ( ym; 5 ; 2 ) ) + 1
] ;
    Case (
        m = 13 ;
        (y + 1) * 100 + 1 ;
        y * 100 + m
    )
)

Let (
[
    _num = Int ( num ) ;
    _text = Abs ( _num ) & "" ;
    _len = Length ( _text )
] ;

Let ( _result =
    If ( _len > 3 ;
        FormatPrice ( Left ( _text ; _len - 3 ) ) & "," & Right ( _text ; 3 ) ;
        _text
    )
 ;

If ( _num < 0 ; "-" & _result ; _result )
)
)

Let (
  [
    _d = GetAsDate ( d ) ;
    _firstDay = Date ( Month ( _d ) ; 1 ; Year ( _d ) ) ;
    _dow = DayOfWeek ( _firstDay ) ;

    /* その月の「第1週開始（月曜）」を求める */
    _week1Mon =
      Case (
        _dow = 7 ; _firstDay + 2 ;        // 土曜なら次の月曜
        _dow = 1 ; _firstDay + 1 ;        // 日曜なら次の月曜
        _firstDay - ( _dow - 2 )          // それ以外は「その週の月曜（前月に戻ることもある）」
      )
  ] ;

  /* 月初が土日で、その土日自身は第1週に含めない → 0 */
  Case (
    _d < _week1Mon ; 0 ;
    1 + Int ( ( _d - _week1Mon ) / 7 )
  )
)

