CustomFunction.Calculation:
/*
  関数名: GetBizDays
  概要: dateからその日が月の何稼働日目か
  引数:targetDate ( 例 : 2001/08/19 )
  戻り値:Num
  作成日: 2026-02-18
  作成者: Myta
*/

Let (
  [
    d  = targetDate ;
    yd  = Year ( d ) ;
    md  = Month ( d ) ;
    dd = Day ( d )
  ] ;

  GetAsNumber (
    ExecuteSQL ("
        SELECT \"c_月次稼働日数\"
        FROM \"カレンダー\"
        WHERE \"年\" = ?
        AND \"月\" = ?
        AND \"日\" = ?
        " ;
        "" ; "" ;
        yd ; md ; dd
    )
  )
)

