)

CustomFunction.Calculation:
/*
  関数名: FYtoYMList
  概要: YYYY形式の文字列からその年度に属する年月のリストを取得する
  引数:
    ym : YYYY（例: 2025）
  戻り値:
    YYYYMM¶YYYYMM...
  作成日: 2026-02-25
  作成者: Okada
*/

While (
  [
    i = 0 ;
    ymlist = ""
  ] ;
  i < 12 ;
  [
    d = Date ( 4 + i ; 1 ; 年度 ) ;
    ym = Year ( d ) & Right ( "0" & Month ( d ) ; 2 ) ;
    ymlist = List ( ymlist ; ym ) ;
    i = i + 1
  ] ;
  ymlist
)

